return $input.all().map(item => {
  const c = item.json;
  let score = 100;
  // Penalize for low usage
  if (c.avg_dau < 5) score -= 30;
  else if (c.avg_dau < 10) score -= 15;
  // Penalize for high support tickets
  if (c.support_tickets > 10) score -= 20;
  else if (c.support_tickets > 5) score -= 10;
  // Penalize for inactivity
  const daysSince = Math.floor((new Date() - new Date(c.last_active)) / 86400000);
  if (daysSince > 14) score -= 25;
  const status = score >= 80 ? 'Healthy' : score >= 60 ? 'At Risk' : 'Critical';
  return { json: { ...c, health_score: Math.max(0, score), health_status: status } };
});
